import sys
from collections import defaultdict, deque

def is_cthulhu(n, edges):
    if n < 3:
        return False

    graph = defaultdict(list)
    degree = [0] * (n + 1)

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        degree[u] += 1
        degree[v] += 1

    leaves = [i for i in range(1, n + 1) if degree[i] == 1]

    while leaves:
        new_leaves = []
        for leaf in leaves:
            if degree[leaf] == 0:
                continue
            neighbor = graph[leaf][0]
            degree[neighbor] -= 1
            if degree[neighbor] == 1:
                new_leaves.append(neighbor)
            degree[leaf] = 0
        leaves = new_leaves

    cycle_nodes = [i for i in range(1, n + 1)	if degree[i] > 1]

    if len(cycle_nodes) < 3:
        return False

    visited = [False] * (n + 1)
    stack = [cycle_nodes[0]]
    visited[cycle_nodes[0]] = True
    cycle_length = 0

    while stack:
        current = stack.pop()
        cycle_length += 1
        for neighbor in graph[current]:
            if degree[neighbor] > 1:
                if visited[neighbor]:
                    return cycle_length == len(cycle_nodes)
                visited[neighbor] = True
                stack.append(neighbor)

    return False

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    edges = [(int(input[2 + 2 * i]), int(input[3 + 2 * i])) for i in range(m)]
    if is_cthulhu(n, edges):
        print("FHTAGN!")
